  r = await req('/posts', { method: 'POST', token: TA, body: { assessmentResultId: rid, bounty: 30, note: '求解读' } });
  assert(r.status === 201, `发帖成功 id=${r.data.post.id}`);
  const pid = r.data.post.id;
