:root {
  --bg: #0f1024;
  --bg-soft: #171935;
  --card: #1e2147;
  --card-hover: #24285a;
  --line: #2e3268;
  --text: #eef0ff;
  --text-dim: #a6abd8;
  --text-faint: #7479ad;
  --primary: #7c6cff;
  --primary-soft: #4a3faa;
  --primary-glow: rgba(124, 108, 255, 0.35);
  --gold: #f5b544;
  --gold-soft: rgba(245, 181, 68, 0.15);
  --green: #43d39e;
  --red: #ff6b81;
  --cyan: #56c8ff;
  --radius: 16px;
  --shadow: 0 12px 40px rgba(0, 0, 0, 0.35);
  font-family: 'PingFang SC', 'Microsoft YaHei', 'Segoe UI', system-ui, sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body, #app {
  min-height: 100vh;
}

body {
  background:
    radial-gradient(1000px 600px at 85% -10%, rgba(124, 108, 255, 0.18), transparent 60%),
    radial-gradient(800px 500px at -10% 20%, rgba(86, 200, 255, 0.10), transparent 60%),
    var(--bg);
  color: var(--text);
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; }
input, textarea { font-family: inherit; }

.container {
  max-width: 1080px;
  margin: 0 auto;
  padding: 0 20px 60px;
}

/* ---------- 通用按钮 ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border: 1px solid transparent;
  border-radius: 10px;
  padding: 9px 18px;
  font-size: 14px;
  font-weight: 600;
  transition: transform 0.15s, box-shadow 0.15s, background 0.15s, opacity 0.15s;
  white-space: nowrap;
}
.btn:active { transform: scale(0.97); }
.btn:disabled { opacity: 0.5; cursor: not-allowed; }
.btn-primary {
  background: linear-gradient(135deg, var(--primary), #9a86ff);
  color: #fff;
  box-shadow: 0 6px 18px var(--primary-glow);
}
.btn-primary:hover:not(:disabled) { box-shadow: 0 8px 26px var(--primary-glow); }
.btn-ghost {
  background: transparent;
  border-color: var(--line);
  color: var(--text-dim);
}
.btn-ghost:hover:not(:disabled) { border-color: var(--primary); color: var(--text); }
.btn-gold {
  background: linear-gradient(135deg, #f5b544, #ffd27a);
  color: #3d2a06;
  box-shadow: 0 6px 18px rgba(245, 181, 68, 0.3);
}
.btn-sm { padding: 6px 12px; font-size: 13px; border-radius: 8px; }
.btn-block { width: 100%; }

/* ---------- 表单 ---------- */
.field { margin-bottom: 14px; }
.field label {
  display: block;
  font-size: 13px;
  color: var(--text-dim);
  margin-bottom: 6px;
}
.input, .textarea {
  width: 100%;
  background: var(--bg-soft);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 11px 14px;
  color: var(--text);
  font-size: 14px;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}
.input:focus, .textarea:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px var(--primary-glow);
}
.textarea { resize: vertical; min-height: 84px; }

/* ---------- 标签 ---------- */
.tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 10px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
}
.tag-open { background: rgba(67, 211, 158, 0.14); color: var(--green); }
.tag-settled { background: rgba(245, 181, 68, 0.14); color: var(--gold); }
.tag-coin { background: var(--gold-soft); color: var(--gold); }

/* ---------- 弹窗 ---------- */
.modal-mask {
  position: fixed;
  inset: 0;
  background: rgba(8, 9, 24, 0.72);
  backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
  padding: 20px;
}
.modal {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 28px;
}
.modal h3 { font-size: 19px; margin-bottom: 4px; }
.modal .sub { color: var(--text-dim); font-size: 13px; margin-bottom: 20px; }
.modal-close {
  float: right;
  background: none;
  border: none;
  color: var(--text-faint);
  font-size: 20px;
  line-height: 1;
}

/* ---------- 轻提示 ---------- */
.toast {
  position: fixed;
  top: 24px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 200;
  padding: 11px 22px;
  border-radius: 10px;
  font-size: 14px;
  font-weight: 500;
  box-shadow: var(--shadow);
  animation: toast-in 0.25s ease;
}
.toast-success { background: #1d4a3c; color: #8ff0c9; border: 1px solid #2e6b57; }
.toast-error { background: #52263a; color: #ffb3c1; border: 1px solid #7a3a55; }
@keyframes toast-in {
  from { opacity: 0; transform: translate(-50%, -12px); }
  to { opacity: 1; transform: translate(-50%, 0); }
}

.empty {
  text-align: center;
  color: var(--text-faint);
  padding: 56px 20px;
  font-size: 14px;
}
.empty .big { font-size: 34px; display: block; margin-bottom: 10px; }

::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-thumb { background: var(--line); border-radius: 4px; }
::-webkit-scrollbar-track { background: transparent; }

