// 使用 Edge/Chrome DevTools Protocol 驱动无头浏览器：注入登录态并逐页截图
import { spawn } from 'child_process'
import { writeFileSync, mkdirSync } from 'fs'

const EDGE = 'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe'
const OUT = 'C:/Users/gongz/AppData/Local/Temp/mbti-shots'
const BASE = 'http://127.0.0.1:5310'
mkdirSync(OUT, { recursive: true })

const PORT = 9222
const userDir = 'C:/Users/gongz/AppData/Local/Temp/edge-cdp-profile'
const edge = spawn(EDGE, [
  '--headless=new',
  `--remote-debugging-port=${PORT}`,
  `--user-data-dir=${userDir}`,
  '--disable-gpu',
  '--no-first-run',
  '--window-size=1280,2400',
  'about:blank',
])

const sleep = (ms) => new Promise(r => setTimeout(r, ms))

async function getWebSocket() {
  for (let i = 0; i < 30; i++) {
    try {
      const r = await fetch(`http://127.0.0.1:${PORT}/json/new?${BASE}/`)
      if (r.ok) return await r.json()
    } catch {}
